import osimport ioimport zipfileimport textwrapimport subprocessimport shleximport shutilimport requestsimport urllib3import xml.etree.ElementTree as ETfrom datetime import datetimefrom flask import Flask, request, send_file, render_template, Response, stream_with_context, jsonify# Deshabilitar warnings de SSL para labsurllib3.disable_warnings(urllib3.exceptions.InsecureRequestWarning)app = Flask(__name__)# ==============================================================================# LÓGICA DE INGENIERÍA# ==============================================================================def cidr_to_ip_mask(cidr):    if not cidr: return "0.0.0.0 0.0.0.0"    try:        if '/' not in cidr: return f"{cidr} 255.255.255.255"        ip_addr, mask_len = cidr.split('/')        mask_len = int(mask_len)        mask = (0xffffffff << (32 - mask_len)) & 0xffffffff        mask_str = ".".join(str((mask >> i) & 0xff) for i in [24, 16, 8, 0])        return f"{ip_addr} {mask_str}"    except: return f"{cidr}"def get_pa_crypto_config(profile):    # NOTA: Palo Alto NO soporta DES simple, mínimo 3DES    config = {        "DES-SHA256": {"encryption": ["3des"], "hash": ["sha256"], "esp_encryption": ["3des"], "esp_authentication": ["sha256"]},        "AES128-SHA256": {"encryption": ["aes-128-cbc"], "hash": ["sha256"], "esp_encryption": ["aes-128-cbc"], "esp_authentication": ["sha256"]},        "AES256-SHA256": {"encryption": ["aes-256-cbc"], "hash": ["sha256"], "esp_encryption": ["aes-256-cbc"], "esp_authentication": ["sha256"]},    }    return config.get(profile, config["AES128-SHA256"])def get_fg_crypto_proposal(profile):    # NOTA: FortiGate usa DES por limitación de licencia    # Cuando tenga licencia, cambiar a 3des-sha256 para compatibilidad con PA    config = {        "DES-SHA256": "des-sha256",        "AES128-SHA256": "aes128-sha256",        "AES256-SHA256": "aes256-sha256",    }    return config.get(profile, config["AES128-SHA256"])# ==============================================================================# GENERADORES DE CONTENIDO# ==============================================================================def generate_vars_content(data, pa_crypto):    fg_lan1_ip_mask = cidr_to_ip_mask(data['fg_lan1_cidr'])    fg_lan2_ip_mask = cidr_to_ip_mask(data['fg_lan2_cidr'])    fg_remote_lan1_ip_mask = cidr_to_ip_mask(data['pa_lan1_cidr'])    fg_remote_lan2_ip_mask = cidr_to_ip_mask(data['pa_lan2_cidr'])        psk = data['psk'].replace("'", "").replace('"', "")    tunnel_mask_ip = "255.255.255.255"    pa_tunnel_cidr = "/32"        return f"""    # --- GLOBAL ---    vpn_name: "{data['tunnel_name']}"    vpn_psk: "{psk}"    # --- CRYPTO ---    phase1_proposal: "{get_fg_crypto_proposal(data['crypto_profile'])}"    phase2_proposal: "{get_fg_crypto_proposal(data['crypto_profile'])}"    dh_group: "{data['dh_group']}"    pa_enc_algo: "{pa_crypto['esp_encryption'][0]}"    pa_auth_algo: "{pa_crypto['esp_authentication'][0]}"    # --- FORTIGATE VARS ---    fg_wan_intf: "{data['fg_wan_intf']}"    fg_lan1_intf: "{data['fg_lan1_intf']}"    fg_lan2_intf: "{data['fg_lan2_intf']}"    fg_wan_ip: "{data['fg_wan_ip']}"    fg_vdom: "{data.get('fg_vdom_name', 'root')}"        fg_lan1_cidr_raw: "{data['fg_lan1_cidr']}"    fg_lan2_cidr_raw: "{data['fg_lan2_cidr']}"    fg_lan1_mask: "{fg_lan1_ip_mask}"    fg_lan2_mask: "{fg_lan2_ip_mask}"    fg_remote_lan1_cidr: "{data['pa_lan1_cidr']}"    fg_remote_lan2_cidr: "{data['pa_lan2_cidr']}"    fg_remote_lan1_mask: "{fg_remote_lan1_ip_mask}"    fg_remote_lan2_mask: "{fg_remote_lan2_ip_mask}"    fg_tunnel_ip: "{data['fg_tunnel_ip']} {tunnel_mask_ip}"    fg_remote_tunnel_ip: "{data['pa_remote_tunnel_ip']} {tunnel_mask_ip}"    fg_remote_gw: "{data['pa_remote_wan_ip']}"    # --- PALO ALTO VARS ---    pa_wan_intf: "{data['pa_wan_intf']}"    pa_lan1_intf: "{data['pa_lan1_intf']}"    pa_lan2_intf: "{data['pa_lan2_intf']}"    pa_zone: "{data.get('pa_zone_name', 'VPN_Zone')}"    pa_lan1_cidr: "{data['pa_lan1_cidr']}"    pa_lan2_cidr: "{data['pa_lan2_cidr']}"    pa_remote_lan1_cidr: "{data['fg_lan1_cidr']}"    pa_remote_lan2_cidr: "{data['fg_lan2_cidr']}"    pa_wan_ip: "{data['pa_wan_ip']}"    pa_tunnel_ip: "{data['pa_tunnel_ip']}{pa_tunnel_cidr}"    pa_peer_ip: "{data['fg_remote_wan_ip']}"    pa_nexthop_ip: "{data['fg_remote_tunnel_ip_pa']}"    pa_provider:      ip_address: "{data['pa_mgmt_ip']}"      username: "{data['pa_user']}"      password: "{data['pa_password']}""""def generate_hosts_yml(data):    return f"""all:  children:    fortigates:      hosts:        forti_site_a:          ansible_host: {data['fg_mgmt_ip']}          ansible_user: "{data['fg_user']}"          ansible_password: "{data['fg_password']}"          ansible_connection: httpapi          ansible_network_os: fortinet.fortios.fortios          ansible_httpapi_use_ssl: yes          ansible_httpapi_validate_certs: no          ansible_httpapi_port: 443          ansible_command_timeout: 60          ansible_connect_timeout: 30    paloaltos:      hosts:        palo_site_b:          ansible_host: {data['pa_mgmt_ip']}          ansible_user: "{data['pa_user']}"          ansible_password: "{data['pa_password']}"          ansible_connection: local"""def generate_site_yml_template():    return """---# ==============================================================================# VPN SITE-TO-SITE: FORTIGATE <-> PALO ALTO# Generado automaticamente# ==============================================================================# PLAY 0: PREPARACIÓN DEL ENTORNO- name: Instalar dependencias requeridas para Palo Alto  hosts: localhost  connection: local  gather_facts: yes  tasks:    - name: Detectar intérprete de Python      debug:        msg: "Usando Python: {{ ansible_playbook_python }}"        - name: Instalar setuptools      ansible.builtin.pip:        name: setuptools        state: latest        executable: pip3      ignore_errors: yes        - name: Instalar librerías Palo Alto (pan-python)      ansible.builtin.pip:        name:          - pan-python          - pan-os-python          - xmltodict          - requests        state: present        executable: pip3      ignore_errors: yes          - name: Verificar instalación de pan-os-python      ansible.builtin.command:        cmd: python3 -c "import pan.xapi; print('pan-os-python OK')"      register: verify_pan      changed_when: false      ignore_errors: yes          - name: Mostrar resultado de verificación      debug:        msg: "{{ verify_pan.stdout if verify_pan.rc == 0 else 'Error: pan-os-python no instalado correctamente' }}"# PLAY 1: FORTIGATE- name: Configurar Overlay FortiGate  hosts: fortigates  connection: httpapi  gather_facts: no  collections:    - fortinet.fortios    vars:__VARS_BLOCK__  tasks:    - name: Configurar VPN Phase 1 (IKE Gateway)      fortios_vpn_ipsec_phase1_interface:        vdom: "{{ fg_vdom }}"        state: "present"        vpn_ipsec_phase1_interface:          name: "{{ vpn_name }}"          interface: "{{ fg_wan_intf }}"           ike_version: "2"          peertype: "any"          net_device: "disable"          proposal: "{{ phase1_proposal }}"          dhgrp: "{{ dh_group }}"          remote_gw: "{{ fg_remote_gw }}"           psksecret: "{{ vpn_psk }}"          nattraversal: "disable"      ignore_errors: yes    - name: Configurar VPN Phase 2 (IPsec SA)      fortios_vpn_ipsec_phase2_interface:        vdom: "{{ fg_vdom }}"        state: "present"        vpn_ipsec_phase2_interface:          name: "{{ vpn_name }}-P2"          phase1name: "{{ vpn_name }}"          proposal: "{{ phase2_proposal }}"          dhgrp: "{{ dh_group }}"          keylifeseconds: 3600          src_subnet: "0.0.0.0 0.0.0.0"           dst_subnet: "0.0.0.0 0.0.0.0"          auto_negotiate: "enable"      ignore_errors: yes    - name: Configurar Interfaz Túnel (VTI)      fortios_system_interface:        vdom: "{{ fg_vdom }}"        state: "present"        system_interface:          name: "{{ vpn_name }}"          vdom: "{{ fg_vdom }}"          type: "tunnel"          interface: "{{ fg_wan_intf }}"          ip: "{{ fg_tunnel_ip }}"          remote_ip: "{{ fg_remote_tunnel_ip }}"          allowaccess: "ping"    # --- OBJETOS DE RED ---    - name: Obj LAN Remota 1      fortios_firewall_address:        vdom: "{{ fg_vdom }}"        state: "present"        firewall_address:            name: "REMOTE_LAN1_{{ fg_remote_lan1_cidr | regex_replace('/', '_') }}"            subnet: "{{ fg_remote_lan1_mask }}"     - name: Obj LAN Remota 2      fortios_firewall_address:        vdom: "{{ fg_vdom }}"        state: "present"        firewall_address:            name: "REMOTE_LAN2_{{ fg_remote_lan2_cidr | regex_replace('/', '_') }}"            subnet: "{{ fg_remote_lan2_mask }}"     - name: Obj LAN Local 1      fortios_firewall_address:        vdom: "{{ fg_vdom }}"        state: "present"        firewall_address:            name: "LOCAL_LAN1_{{ fg_lan1_cidr_raw | regex_replace('/', '_') }}"            subnet: "{{ fg_lan1_mask }}"    - name: Obj LAN Local 2      fortios_firewall_address:        vdom: "{{ fg_vdom }}"        state: "present"        firewall_address:            name: "LOCAL_LAN2_{{ fg_lan2_cidr_raw | regex_replace('/', '_') }}"            subnet: "{{ fg_lan2_mask }}"    # --- ENRUTAMIENTO ESTÁTICO ---    - name: Ruta a Remote LAN 1      fortios_router_static:        vdom: "{{ fg_vdom }}"        state: "present"        router_static:          seq_num: "10"          dst: "{{ fg_remote_lan1_mask }}"                device: "{{ vpn_name }}"    - name: Ruta a Remote LAN 2      fortios_router_static:        vdom: "{{ fg_vdom }}"        state: "present"        router_static:          seq_num: "11"          dst: "{{ fg_remote_lan2_mask }}"          device: "{{ vpn_name }}"    # --- POLÍTICAS DE FIREWALL ---    - name: Politica Salida (LAN -> VPN)      fortios_firewall_policy:        vdom: "{{ fg_vdom }}"        state: "present"        firewall_policy:          policyid: "100"          name: "LAN-to-VPN"          srcintf:            - name: "{{ fg_lan1_intf }}"            - name: "{{ fg_lan2_intf }}"          dstintf:            - name: "{{ vpn_name }}"          srcaddr:             - name: "LOCAL_LAN1_{{ fg_lan1_cidr_raw | regex_replace('/', '_') }}"            - name: "LOCAL_LAN2_{{ fg_lan2_cidr_raw | regex_replace('/', '_') }}"          dstaddr:             - name: "REMOTE_LAN1_{{ fg_remote_lan1_cidr | regex_replace('/', '_') }}"            - name: "REMOTE_LAN2_{{ fg_remote_lan2_cidr | regex_replace('/', '_') }}"          action: "accept"          schedule: "always"          service:             - name: "ALL"          nat: "disable"           logtraffic: "all"    - name: Politica Entrada (VPN -> LAN)      fortios_firewall_policy:        vdom: "{{ fg_vdom }}"        state: "present"        firewall_policy:          policyid: "101"          name: "VPN-to-LAN"          srcintf:            - name: "{{ vpn_name }}"          dstintf:            - name: "{{ fg_lan1_intf }}"            - name: "{{ fg_lan2_intf }}"          srcaddr:             - name: "REMOTE_LAN1_{{ fg_remote_lan1_cidr | regex_replace('/', '_') }}"            - name: "REMOTE_LAN2_{{ fg_remote_lan2_cidr | regex_replace('/', '_') }}"          dstaddr:             - name: "LOCAL_LAN1_{{ fg_lan1_cidr_raw | regex_replace('/', '_') }}"            - name: "LOCAL_LAN2_{{ fg_lan2_cidr_raw | regex_replace('/', '_') }}"          action: "accept"          schedule: "always"          service:             - name: "ALL"          nat: "disable"           logtraffic: "all"# PLAY 2: PALO ALTO- name: Configurar Overlay Palo Alto  hosts: paloaltos  connection: local  gather_facts: no  collections:    - paloaltonetworks.panos    vars:__VARS_BLOCK__  tasks:    # PASO 1: Crear la zona VPN primero (necesaria para asignar el tunnel)    - name: Crear Zona VPN      panos_zone:        provider: "{{ pa_provider }}"        zone: "{{ pa_zone }}"        mode: layer3    # PASO 2: Crear la interfaz tunnel usando panos_tunnel (NO panos_interface)    - name: Crear Interfaz Túnel      panos_tunnel:        provider: "{{ pa_provider }}"        if_name: "tunnel.1"        ip: ["{{ pa_tunnel_ip }}"]        vr_name: "default"        zone_name: "{{ pa_zone }}"        commit: False    - name: Perfil IKE      panos_ike_crypto_profile:        provider: "{{ pa_provider }}"        name: "{{ vpn_name }}-IKE"        dh_group: ["group{{ dh_group }}"]        encryption: ["{{ pa_enc_algo }}"]        authentication: ["{{ pa_auth_algo }}"]        lifetime_seconds: 43200        commit: False    - name: Perfil IPsec      panos_ipsec_profile:        provider: "{{ pa_provider }}"        name: "{{ vpn_name }}-IPSEC"        dh_group: "group{{ dh_group }}"        esp_encryption: ["{{ pa_enc_algo }}"]        esp_authentication: ["{{ pa_auth_algo }}"]        lifetime_seconds: 3600        commit: False    - name: IKE Gateway      panos_ike_gateway:        provider: "{{ pa_provider }}"        name: "{{ vpn_name }}-GW"        version: "ikev2"        interface: "{{ pa_wan_intf }}"            peer_ip_value: "{{ pa_peer_ip }}"        pre_shared_key: "{{ vpn_psk }}"        ikev2_crypto_profile: "{{ vpn_name }}-IKE"        enable_liveness_check: true        liveness_check_interval: 5        commit: False    - name: IPSec Tunnel      panos_ipsec_tunnel:        provider: "{{ pa_provider }}"        name: "{{ vpn_name }}"        tunnel_interface: "tunnel.1"        ak_ike_gateway: "{{ vpn_name }}-GW"        ak_ipsec_crypto_profile: "{{ vpn_name }}-IPSEC"        commit: False    - name: Proxy ID      panos_config_element:        provider: "{{ pa_provider }}"        xpath: "/config/devices/entry[@name='localhost.localdomain']/network/tunnel/ipsec/entry[@name='{{ vpn_name }}']/auto-key/proxy-id"        element: |          <entry name="Wildcard-S2S">            <local>0.0.0.0/0</local>            <remote>0.0.0.0/0</remote>          </entry>        commit: False    - name: Ruta Estática LAN 1 (a FG)      panos_static_route:        provider: "{{ pa_provider }}"        name: "Ruta-a-FG-LAN1"        destination: "{{ pa_remote_lan1_cidr }}"         nexthop_type: "ip-address"        nexthop: "{{ pa_nexthop_ip }}"        interface: "tunnel.1"        virtual_router: "default"        commit: False    - name: Ruta Estática LAN 2 (a FG)      panos_static_route:        provider: "{{ pa_provider }}"        name: "Ruta-a-FG-LAN2"        destination: "{{ pa_remote_lan2_cidr }}"         nexthop_type: "ip-address"        nexthop: "{{ pa_nexthop_ip }}"        interface: "tunnel.1"        virtual_router: "default"        commit: False    - name: Policy Trust-VPN (Salida)      panos_security_rule:        provider: "{{ pa_provider }}"        rule_name: "Permitir_Salida_{{ vpn_name }}"        source_zone: ["trust"]        destination_zone: ["{{ pa_zone }}"]        source_ip: ["any"]        destination_ip: ["{{ pa_remote_lan1_cidr }}", "{{ pa_remote_lan2_cidr }}"]        action: "allow"        commit: False    - name: Policy VPN-Trust (Entrada)      panos_security_rule:        provider: "{{ pa_provider }}"        rule_name: "Permitir_Entrada_{{ vpn_name }}"        source_zone: ["{{ pa_zone }}"]        destination_zone: ["trust"]        source_ip: ["{{ pa_remote_lan1_cidr }}", "{{ pa_remote_lan2_cidr }}"]        destination_ip: ["any"]        action: "allow"        commit: False    - name: COMMIT      paloaltonetworks.panos.panos_commit_firewall:        provider: "{{ pa_provider }}""""def generate_readme():    return """# VPN Site-to-Site Orchestrator## FortiGate <-> Palo Alto### Archivos Generados:- `hosts.yml` - Inventario de dispositivos- `site.yml` - Playbook principal- `ansible.cfg` - Configuración de Ansible### Pre-requisitos IMPORTANTES:#### 1. Ansible y Python```bash# Ansible 2.9 o superiorpip3 install ansible# Librerías Python necesariaspip3 install pan-python pan-os-python xmltodict requests setuptools```#### 2. Colecciones de Ansible```bash# Colección FortiGateansible-galaxy collection install fortinet.fortios# Colección Palo Altoansible-galaxy collection install paloaltonetworks.panos```#### 3. Verificar instalación```bash# Verificar que pan-os-python está instaladopython3 -c "import pan.xapi; print('pan-os-python OK')"# Verificar coleccionesansible-galaxy collection list```### Ejecución:```bashansible-playbook site.yml```### Troubleshooting:**Error: "Missing required library pan-os-python"**- Solución: `pip3 install pan-os-python pan-python`- Si usas virtualenv, actívalo antes: `source venv/bin/activate`**Error: "Collection fortinet.fortios not found"**- Solución: `ansible-galaxy collection install fortinet.fortios`**Error: "Connection timeout"**- Verifica conectividad: `ping <IP_DISPOSITIVO>`- Verifica puertos: FortiGate=443, PaloAlto=443- Verifica credenciales en hosts.yml### Notas:- El playbook intenta instalar dependencias automáticamente- Si falla, instálalas manualmente con los comandos de arriba- Asegúrate de tener acceso de red a los dispositivosGenerado: """ + datetime.now().strftime("%Y-%m-%d %H:%M:%S")# ==============================================================================# VERIFICACIÓN DE CONECTIVIDAD# ==============================================================================def test_connectivity(host, timeout=5):    """Prueba conectividad básica con un host"""    import socket    try:        socket.setdefaulttimeout(timeout)        socket.socket(socket.AF_INET, socket.SOCK_STREAM).connect((host, 443))        return True, "Conectado"    except socket.timeout:        return False, "Timeout"    except socket.error as e:        return False, f"Error: {str(e)}"# ==============================================================================# EXTRACCIÓN DE INFO DE DISPOSITIVOS# ==============================================================================def extract_fortigate_info(host, username, password, interfaces):    """Extrae información de interfaces de FortiGate via API REST"""    result = {        'success': False,        'error': None,        'interfaces': {}    }        try:        # Login y obtener token        login_url = f"https://{host}/logincheck"        session = requests.Session()        session.verify = False                login_data = {            'username': username,            'secretkey': password        }                resp = session.post(login_url, data=login_data, timeout=10)                # Verificar si hay CSRF token en cookies        csrf_token = None        for cookie in session.cookies:            if 'ccsrftoken' in cookie.name.lower():                csrf_token = cookie.value.strip('"')                break                if not csrf_token:            # Intentar obtener de otra forma            csrf_token = session.cookies.get('ccsrftoken', '').strip('"')                headers = {}        if csrf_token:            headers['X-CSRFTOKEN'] = csrf_token                # Obtener info de cada interfaz        for intf_name in interfaces:            api_url = f"https://{host}/api/v2/cmdb/system/interface/{intf_name}"            resp = session.get(api_url, headers=headers, timeout=10)                        if resp.status_code == 200:                data = resp.json()                if 'results' in data and len(data['results']) > 0:                    intf_data = data['results'][0]                    ip = intf_data.get('ip', '0.0.0.0 0.0.0.0')                    # Formato: "10.1.1.1 255.255.255.0" -> "10.1.1.1/24"                    if isinstance(ip, str) and ' ' in ip:                        ip_parts = ip.split()                        if len(ip_parts) == 2:                            ip_addr = ip_parts[0]                            mask = ip_parts[1]                            # Convertir máscara a CIDR                            cidr = sum(bin(int(x)).count('1') for x in mask.split('.'))                            ip = f"{ip_addr}/{cidr}"                                        result['interfaces'][intf_name] = {                        'ip': ip,                        'status': intf_data.get('status', 'unknown'),                        'type': intf_data.get('type', 'unknown')                    }            else:                result['interfaces'][intf_name] = {'ip': None, 'error': f"HTTP {resp.status_code}"}                # Logout        session.get(f"https://{host}/logout", headers=headers, timeout=5)                result['success'] = True            except requests.exceptions.Timeout:        result['error'] = "Timeout conectando a FortiGate"    except requests.exceptions.ConnectionError:        result['error'] = "No se puede conectar a FortiGate"    except Exception as e:        result['error'] = str(e)        return resultdef extract_paloalto_info(host, username, password, interfaces):    """Extrae información de interfaces de Palo Alto via API XML"""    result = {        'success': False,        'error': None,        'interfaces': {}    }        try:        # Obtener API key        keygen_url = f"https://{host}/api/?type=keygen&user={username}&password={password}"        resp = requests.get(keygen_url, verify=False, timeout=10)                if resp.status_code != 200:            result['error'] = f"Error autenticando: HTTP {resp.status_code}"            return result                # Parsear XML para obtener key        root = ET.fromstring(resp.text)        key_elem = root.find('.//key')        if key_elem is None:            result['error'] = "No se pudo obtener API key"            return result                api_key = key_elem.text                # Obtener configuración de interfaces        # Primero ethernet interfaces        config_url = f"https://{host}/api/?type=config&action=get&xpath=/config/devices/entry[@name='localhost.localdomain']/network/interface&key={api_key}"        resp = requests.get(config_url, verify=False, timeout=10)                if resp.status_code == 200:            root = ET.fromstring(resp.text)                        for intf_name in interfaces:                # Buscar en ethernet                if intf_name.startswith('ethernet'):                    # ethernet1/1 -> entry[@name='ethernet1/1']                    xpath_parts = intf_name.split('/')                    if len(xpath_parts) == 2:                        slot = xpath_parts[0]  # ethernet1                        port = xpath_parts[1]  # 1                                                # Buscar en la respuesta                        for ethernet in root.findall(f".//ethernet/entry[@name='{slot}']"):                            layer3 = ethernet.find('layer3')                            if layer3 is not None:                                for unit in layer3.findall(f".//units/entry[@name='{slot}/{port}']"):                                    ip_elem = unit.find('.//ip/entry')                                    if ip_elem is not None:                                        result['interfaces'][intf_name] = {                                            'ip': ip_elem.get('name', 'N/A'),                                            'status': 'configured'                                        }                                        break                                # También buscar IP directamente en layer3                                ip_elem = layer3.find('.//ip/entry')                                if ip_elem is not None and intf_name not in result['interfaces']:                                    result['interfaces'][intf_name] = {                                        'ip': ip_elem.get('name', 'N/A'),                                        'status': 'configured'                                    }                                if intf_name not in result['interfaces']:                    result['interfaces'][intf_name] = {'ip': None, 'error': 'No encontrada'}                # También obtener info operacional        op_url = f"https://{host}/api/?type=op&cmd=<show><interface>all</interface></show>&key={api_key}"        resp = requests.get(op_url, verify=False, timeout=10)                if resp.status_code == 200:            root = ET.fromstring(resp.text)            for entry in root.findall('.//ifnet/entry'):                name = entry.find('name')                ip = entry.find('ip')                if name is not None and ip is not None:                    intf_name = name.text                    if intf_name in interfaces:                        ip_text = ip.text if ip.text else 'N/A'                        if ip_text != 'N/A' and ip_text != '':                            result['interfaces'][intf_name] = {                                'ip': ip_text,                                'status': 'up'                            }                result['success'] = True            except requests.exceptions.Timeout:        result['error'] = "Timeout conectando a Palo Alto"    except requests.exceptions.ConnectionError:        result['error'] = "No se puede conectar a Palo Alto"    except ET.ParseError as e:        result['error'] = f"Error parseando respuesta XML: {e}"    except Exception as e:        result['error'] = str(e)        return result# ==============================================================================# RUTAS DEL SERVIDOR FLASK# ==============================================================================@app.route('/')def index():    return render_template('frontend.html')@app.route('/install-dependencies', methods=['POST'])def install_dependencies():    """Instala y verifica todas las dependencias necesarias"""    def generate_install_log():        try:            yield "[INFO] Iniciando instalación de dependencias...\n"            yield "=" * 60 + "\n"                        # 1. Verificar pip            yield "[STEP 1/5] Verificando pip...\n"            try:                result = subprocess.run(                    ["pip3", "--version"],                    capture_output=True,                    text=True,                    timeout=10                )                if result.returncode == 0:                    yield f"[SUCCESS] pip3 encontrado: {result.stdout.strip()}\n"                else:                    yield "[ERROR] pip3 no está disponible\n"                    return            except Exception as e:                yield f"[ERROR] Error verificando pip: {str(e)}\n"                return                        # 2. Actualizar pip y setuptools            yield "\n[STEP 2/5] Actualizando pip y setuptools...\n"            try:                result = subprocess.run(                    ["pip3", "install", "--upgrade", "pip", "setuptools", "wheel"],                    capture_output=True,                    text=True,                    timeout=120                )                if result.returncode == 0:                    yield "[SUCCESS] pip y setuptools actualizados\n"                else:                    yield f"[WARN] Advertencia al actualizar: {result.stderr[:200]}\n"            except Exception as e:                yield f"[WARN] No se pudo actualizar pip: {str(e)}\n"                        # 3. Instalar librerías Python para Palo Alto            yield "\n[STEP 3/5] Instalando librerías Python (pan-os-python, xmltodict, requests)...\n"            packages = ["pan-python", "pan-os-python", "xmltodict", "requests"]            for package in packages:                try:                    yield f"  → Instalando {package}...\n"                    result = subprocess.run(                        ["pip3", "install", "--upgrade", package],                        capture_output=True,                        text=True,                        timeout=120                    )                    if result.returncode == 0:                        yield f"  [SUCCESS] {package} instalado correctamente\n"                    else:                        yield f"  [ERROR] Error instalando {package}: {result.stderr[:200]}\n"                except Exception as e:                    yield f"  [ERROR] Excepción instalando {package}: {str(e)}\n"                        # 4. Instalar colecciones de Ansible            yield "\n[STEP 4/5] Instalando colecciones de Ansible...\n"            collections = [                "fortinet.fortios",                "paloaltonetworks.panos"            ]            for collection in collections:                try:                    yield f"  → Instalando {collection}...\n"                    result = subprocess.run(                        ["ansible-galaxy", "collection", "install", collection, "--force"],                        capture_output=True,                        text=True,                        timeout=180                    )                    if result.returncode == 0:                        yield f"  [SUCCESS] {collection} instalado correctamente\n"                    else:                        yield f"  [WARN] Advertencia al instalar {collection}: {result.stderr[:200]}\n"                except Exception as e:                    yield f"  [ERROR] Error instalando {collection}: {str(e)}\n"                        # 5. Verificación final            yield "\n[STEP 5/5] Verificando instalación...\n"            yield "=" * 60 + "\n"                        # Verificar pan-os-python            try:                result = subprocess.run(                    ["python3", "-c", "import pan.xapi; print('pan-os-python OK')"],                    capture_output=True,                    text=True,                    timeout=10                )                if result.returncode == 0:                    yield "[SUCCESS] ✓ pan-os-python verificado correctamente\n"                else:                    yield "[ERROR] ✗ pan-os-python no se pudo importar\n"            except Exception as e:                yield f"[ERROR] Error verificando pan-os-python: {str(e)}\n"                        # Verificar xmltodict            try:                result = subprocess.run(                    ["python3", "-c", "import xmltodict; print('xmltodict OK')"],                    capture_output=True,                    text=True,                    timeout=10                )                if result.returncode == 0:                    yield "[SUCCESS] ✓ xmltodict verificado correctamente\n"                else:                    yield "[WARN] ✗ xmltodict no se pudo importar\n"            except Exception as e:                yield f"[WARN] Error verificando xmltodict: {str(e)}\n"                        # Verificar colecciones            try:                result = subprocess.run(                    ["ansible-galaxy", "collection", "list"],                    capture_output=True,                    text=True,                    timeout=10                )                if "fortinet.fortios" in result.stdout and "paloaltonetworks.panos" in result.stdout:                    yield "[SUCCESS] ✓ Colecciones de Ansible verificadas\n"                else:                    yield "[WARN] ✗ Algunas colecciones pueden no estar instaladas\n"            except Exception as e:                yield f"[WARN] Error verificando colecciones: {str(e)}\n"                        yield "\n" + "=" * 60 + "\n"            yield "[COMPLETE] Proceso de instalación finalizado\n"            yield "[INFO] Si hay errores, revisa los permisos y la conexión a internet\n"                    except Exception as e:            yield f"\n[CRITICAL ERROR] Error general: {str(e)}\n"        return Response(stream_with_context(generate_install_log()), mimetype='text/plain')@app.route('/test-connectivity', methods=['POST'])def test_devices():    """Verifica conectividad con los dispositivos antes de ejecutar"""    try:        data = request.json        results = {            'fortigate': {},            'paloalto': {}        }                # Test FortiGate        fg_ok, fg_msg = test_connectivity(data['fg_mgmt_ip'])        results['fortigate'] = {'success': fg_ok, 'message': fg_msg, 'ip': data['fg_mgmt_ip']}                # Test Palo Alto        pa_ok, pa_msg = test_connectivity(data['pa_mgmt_ip'])        results['paloalto'] = {'success': pa_ok, 'message': pa_msg, 'ip': data['pa_mgmt_ip']}                return jsonify(results)    except Exception as e:        return jsonify({'error': str(e)}), 500@app.route('/extract-info', methods=['POST'])def extract_info():    """Extrae información de interfaces de ambos dispositivos"""    try:        data = request.json        results = {            'fortigate': {'success': False, 'interfaces': {}},            'paloalto': {'success': False, 'interfaces': {}}        }                # Extraer de FortiGate        fg_interfaces = [            data.get('fg_wan_intf', 'port1'),            data.get('fg_lan1_intf', 'port2'),            data.get('fg_lan2_intf', 'port3')        ]                fg_result = extract_fortigate_info(            data['fg_mgmt_ip'],            data['fg_user'],            data['fg_password'],            fg_interfaces        )        results['fortigate'] = fg_result                # Extraer de Palo Alto        pa_interfaces = [            data.get('pa_wan_intf', 'ethernet1/1'),            data.get('pa_lan1_intf', 'ethernet1/2'),            data.get('pa_lan2_intf', 'ethernet1/3')        ]                pa_result = extract_paloalto_info(            data['pa_mgmt_ip'],            data['pa_user'],            data['pa_password'],            pa_interfaces        )        results['paloalto'] = pa_result                return jsonify(results)    except Exception as e:        return jsonify({'error': str(e)}), 500@app.route('/generate', methods=['POST'])def generate_zip():    """Genera y descarga un ZIP con todos los archivos de configuración"""    try:        data = request.json                if "'" in data.get('psk', '') or '"' in data.get('psk', ''):            return jsonify({"error": "Error: La PSK contiene caracteres no permitidos."}), 400                # Generar contenido        pa_crypto_config = get_pa_crypto_config(data['crypto_profile'])        vars_content = generate_vars_content(data, pa_crypto_config)        vars_indented = textwrap.indent(vars_content, '    ')        site_yml_content = generate_site_yml_template().replace('__VARS_BLOCK__', vars_indented)        hosts_yml_content = generate_hosts_yml(data)        ansible_cfg_content = """[defaults]inventory=./hosts.ymlhost_key_checking=Falsetimeout=30deprecation_warnings=False"""        readme_content = generate_readme()                # Crear ZIP en memoria        zip_buffer = io.BytesIO()        with zipfile.ZipFile(zip_buffer, 'w', zipfile.ZIP_DEFLATED) as zip_file:            zip_file.writestr('hosts.yml', hosts_yml_content)            zip_file.writestr('site.yml', site_yml_content)            zip_file.writestr('ansible.cfg', ansible_cfg_content)            zip_file.writestr('README.md', readme_content)                zip_buffer.seek(0)        timestamp = datetime.now().strftime("%Y%m%d_%H%M%S")        filename = f"vpn_config_{data['tunnel_name']}_{timestamp}.zip"                return send_file(            zip_buffer,            mimetype='application/zip',            as_attachment=True,            download_name=filename        )    except Exception as e:        return jsonify({'error': str(e)}), 500@app.route('/run', methods=['POST'])def run_playbook():    """Genera los archivos y ejecuta Ansible en streaming."""    try:        data = request.json                if "'" in data.get('psk', '') or '"' in data.get('psk', ''):            return jsonify({"error": "Error: La PSK contiene caracteres no permitidos."}), 400                # Generar contenido        pa_crypto_config = get_pa_crypto_config(data['crypto_profile'])        vars_content = generate_vars_content(data, pa_crypto_config)        vars_indented = textwrap.indent(vars_content, '    ')        site_yml_content = generate_site_yml_template().replace('__VARS_BLOCK__', vars_indented)        hosts_yml_content = generate_hosts_yml(data)        ansible_cfg_content = """[defaults]inventory=./hosts.ymlhost_key_checking=Falsetimeout=30deprecation_warnings=False"""                # Workspace único por sesión        timestamp = datetime.now().strftime("%Y%m%d_%H%M%S")        workspace = f"ansible_workspace_{timestamp}"        os.makedirs(workspace, exist_ok=True)                with open(os.path.join(workspace, "hosts.yml"), "w") as f:            f.write(hosts_yml_content)        with open(os.path.join(workspace, "site.yml"), "w") as f:            f.write(site_yml_content)        with open(os.path.join(workspace, "ansible.cfg"), "w") as f:            f.write(ansible_cfg_content)                def generate_log():            try:                cmd = ["ansible-playbook", "site.yml"]                                process = subprocess.Popen(                    cmd,                    cwd=workspace,                    stdout=subprocess.PIPE,                    stderr=subprocess.STDOUT,                    text=True,                    bufsize=1                )                                for line in process.stdout:                    yield line                                process.wait()                                if process.returncode == 0:                    yield "\n[SUCCESS] Ejecución de Ansible finalizada correctamente.\n"                else:                    yield f"\n[ERROR] Ansible finalizó con código de error: {process.returncode}\n"                                # Limpiar workspace después de la ejecución                try:                    shutil.rmtree(workspace)                    yield "[CLEANUP] Workspace temporal eliminado.\n"                except:                    yield "[CLEANUP] No se pudo eliminar el workspace temporal.\n"                                except Exception as e:                yield f"\n[CRITICAL ERROR] No se pudo ejecutar Ansible: {str(e)}\n"                return Response(stream_with_context(generate_log()), mimetype='text/plain')        except Exception as e:        return str(e), 500if __name__ == '__main__':    app.run(host='0.0.0.0', port=5000, debug=True)